import itertools

def is_kawaii(seq):
    max_val = max(seq)
    for k in range(2, max_val + 1):
        if k in seq:
            if k - 1 not in seq:
                return False
            # first occurrence of k-1
            first_k_minus_1 = seq.index(k - 1)
            # last occurrence of k
            last_k = len(seq) - 1 - seq[::-1].index(k)
            if first_k_minus_1 >= last_k:
                return False
    return True

def count_kawaii(n):
    count = 0
    # The elements of the sequence must be positive integers.
    # Since there are n elements, the maximum possible value that can satisfy the 
    # "if k exists, k-1 exists" property is n.
    # So we can iterate through all sequences of length n with elements from {1, ..., n}.
    for seq in itertools.product(range(1, n + 1), repeat=n):
        if is_kawaii(seq):
            count += 1
    return count

for n in range(1, 6):
    print(f"n={n}: {count_kawaii(n)}")

def bell(n):
    bell_tri = [[0] * (n + 1) for _ in range(n + 1)]
    bell_tri[0][0] = 1
    for i in range(1, n + 1):
        bell_tri[i][0] = bell_tri[i - 1][i - 1]
        for j in range(1, i + 1):
            bell_tri[i][j] = bell_tri[i - 1][j - 1] + bell_tri[i][j - 1]
    return bell_tri[n][0]

