def is_rgs(seq):
    if not seq: return True
    if seq[0] != 1: return False
    max_val = 1
    for x in seq[1:]:
        if x > max_val + 1:
            return False
        if x > max_val:
            max_val = x
    return True

def count_rgs(n):
    count = 0
    # RGS elements are from {1, ..., n}
    for seq in itertools.product(range(1, n + 1), repeat=n):
        if is_rgs(seq):
            count += 1
    return count

for n in range(1, 7):
