import itertools

def is_kawaii(seq):
    # "for each positive integer k >= 2, if the number k appears in the sequence 
    # then so does the number k-1, and moreover the first occurrence 
    # of k-1 comes before the last occurrence of k."

    # Find all unique elements in the sequence
    elements = set(seq)
    max_val = max(elements) if elements else 0

    for k in range(2, max_val + 1):
        if k in elements:
            if k - 1 not in elements:
                return False
            # first occurrence of k-1
            first_k_minus_1 = seq.index(k - 1)
            # last occurrence of k
            last_k = len(seq) - 1 - seq[::-1].index(k)
            if first_k_minus_1 >= last_k:
                return False
    return True

def count_kawaii(n):
