def stirling_second(n, k):
    if k == 1 or k == n:
        return 1
    if k > n or k == 0:
        return 0
    return k * stirling_second(n - 1, k) + stirling_second(n - 1, k - 1)

# Memoized version
memo = {}
def stirling_second_memo(n, k):
    if (n, k) in memo:
        return memo[(n, k)]
    if k == 1 or k == n:
        res = 1
    elif k > n or k == 0:
        res = 0
    else:
        res = k * stirling_second_memo(n - 1, k) + stirling_second_memo(n - 1, k - 1)
    memo[(n, k)] = res
    return res

